values.value:
[
  [
    {
      "fieldName": "ucinn_ascendv2__Enable_Recurring_Gift__c",
      "toolTip": "For hiding or showing recurring gift records on the gift processing screen.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Enable Recurring Gift"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Enable_External_Stock_API_Callouts__c",
      "toolTip": "When checked, use external API to lookup company name and low/high stock prices based on stock ticker and date.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Enable External Stock API Callouts"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Keep_External_System_ID_on_New_Record__c",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Keep External System ID on New Record"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Enable_External_Stock_API_Callouts__c",
      "toolTip": "When checked, use external API to lookup company name and low/high stock prices based on stock ticker and date.",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Enable External Stock API Callouts"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Is_Delete_Opportunity_Enabled__c",
      "toolTip": "Allow deletetion of opportunities through gp UI",
      "customFieldParams": {
        "type": "checkbox",
        "label": "Is Delete Opportunity Enabled"
      }
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Opportunity_Deletion_Batch_Threshold__c",
      "toolTip": "When certain Ascend functions try to delete multiple Opportunities at once, they may attempt the deletion as a batch job instead of an immediate deletion. This setting controls the threshold at which that happens.",
      "customFieldParams": {
        "type": "number",
        "label": "Opportunity Deletion Batch Threshold"
      }
    },
    {
      "fieldName": "BLANK_OPP_DELETE_BATCH_THRESHOLD"
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Payment_Processing_Batch_Threshold__c",
      "toolTip": "On the wizard, run a batch if the number of payments in a transaction is greater than or equal to this threshold.",
      "customFieldParams": {
        "type": "number",
        "label": "Payment Processing Batch Threshold"
      }
    },
    {
      "fieldName": "BLANK_PAYMENT_PROCESSING_BATCH_THRESHOLD"
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Custom_Payment_Frequency__c",
      "toolTip": "Construct JSON like {\"Payment Frequency\":{\"Months\":1,\"Days\":1}}. Payment Frequency is the custom Frequency API Name. The order of Months and Days dictates summing order. There needs to be a key of Months or Days. No support for Years key.",
      "jsonFieldParams": {
        "label": "Custom Payment Frequency",
        "type": "object",
        "keyLabel": "Custom Frequency",
        "jsonKeysToValueList": [
          {
            "key": "[CUSTOM]",
            "valueJsonFieldParams": {
              "type": "object",
              "jsonKeysToValueList": [
                {
                  "key": "Months",
                  "valueCustomFieldParams": {
                    "type": "number"
                  }
                },
                {
                  "key": "Days",
                  "valueCustomFieldParams": {
                    "type": "number"
                  }
                }
              ]
            }
          }
        ]
      }
    },
    {
      "fieldName": "BLANK_CUSTOM_PAYMENT_FREQUENCY"
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Auto_Apply_Opp_Hard_Soft_Credits__c",
      "toolTip": "Transaction Types that will auto apply manual credits from the parent opportunity. Use any combination of \"Pledge Payment\" , \"Recurring Gift Payment\", \"Matching Gift Payment\", \"Auto Renewing Membership Payment\", \"Installment Based Membership Payment\", \"Auto Renewing POS Payment\", \"Installment Based POS Payment\", \"Partial Payment POS Payment\" delimited by \";\".",
      "jsonFieldParams": {
        "label": "Auto Apply Opp Hard/Soft Credits",
        "type": "listNotJSON",
        "listNotJSONSeperator": ";",
        "valueCustomFieldParams": {
          "type": "picklist",
          "customPicklistValuesString": [
            "Pledge Payment",
            "Recurring Gift Payment",
            "Matching Gift Payment",
            "Auto Renewing Membership Payment",
            "Installment Based Membership Payment",
            "Auto Renewing POS Payment",
            "Installment Based POS Payment",
            "Partial Payment POS Payment"
          ]
        }
      }
    },
    {
      "fieldName": "BLANK_AUTO_APPLY__OPP_HSC"
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Hard_and_Soft_Credit_Subtype_Mapping__c",
      "toolTip": "Maps HSC created from relationships/affiliations with specific subtype.",
      "jsonFieldParams": {
        "label": "Hard And Soft Credit Subtype Mapping",
        "type": "object",
        "jsonKeysToValueList": [
          {
            "key": "Relationship Defaults",
            "valueJsonFieldParams": {
              "type": "object",
              "keyLabel": "Constituent Role",
              "valueLabel": "HSC Credit Subtype",
              "jsonKeysToValueList": [
                {
                  "key": "[CUSTOM]",
                  "valueCustomFieldParams": {
                    "type": "text"
                  }
                }
              ]
            }
          },
          {
            "key": "Affiliation Defaults",
            "valueJsonFieldParams": {
              "type": "object",
              "keyLabel": "Constituent Role",
              "valueLabel": "HSC Credit Subtype",
              "jsonKeysToValueList": [
                {
                  "key": "[CUSTOM]",
                  "valueCustomFieldParams": {
                    "type": "text"
                  }
                }
              ]
            }
          }
        ]
      }
    },
    {
      "fieldName": "BLANK_HSC_SUBTYPE_MAPPING"
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Session_Fields_To_Track__c",
      "jsonFieldParams": {
        "label": "Session Fields To Track",
        "helpText": "Currency fields to track and display when session is closed",
        "type": "listNotJSON",
        "title": "Session Fields To Track",
        "listNotJSONSeperator": ",",
        "valueCustomFieldParams": {
          "type": "text"
        }
      }
    },
    {
      "fieldName": "BLANK_SESSION_FIELDS_TO_TRACK"
    }
  ],
  [
    {
      "fieldName": "ucinn_ascendv2__Adjustment_History_Columns_v1__c",
      "toolTip": "JSON string to override adjustment history table columns./n/nEx:[ {'fieldName': 'Name'},{'label': 'Adjustment Type','fieldName': 'Adjustment_Type__c'} ]",
      "jsonFieldParams": {
        "label": "Adjustment History Columns",
        "helpText": "Currency fields to track and display when session is closed",
        "type": "list",
        "listType": "object",
        "jsonKeysToValueList": [
          {
            "key": "fieldName",
            "valueCustomFieldParams": {
              "type": "text"
            }
          },
          {
            "key": "label",
            "valueCustomFieldParams": {
              "type": "text"
            }
          }
        ]
      }
    },
    {
      "fieldName": "BLANK_Adjustment_History_Columns_v1"
    }
  ]
]

